import { useEffect, useState } from 'react';
import { useDispatch } from 'react-redux';
import { getServerData } from '../helper/helper';
import * as Action from '../redux/question_reducer';

/** Custom hook — fetches questions from backend and seeds Redux store */
export const useFetchQestion = () => {
    const dispatch = useDispatch();
    const [getData, setGetData] = useState({
        isLoading: false,
        apiData: [],
        serverError: null,
    });

    useEffect(() => {
        setGetData((prev) => ({ ...prev, isLoading: true }));

        (async () => {
            try {
                const [{ questions, answers }] = await getServerData(
                    `/api/questions`,
                    (data) => data
                );

                if (questions.length > 0) {
                    setGetData({ isLoading: false, apiData: questions, serverError: null });
                    dispatch(Action.startExamAction({ question: questions, answers }));
                } else {
                    throw new Error('No Questions Available');
                }
            } catch (error) {
                setGetData({ isLoading: false, apiData: [], serverError: error.message });
            }
        })();
    }, [dispatch]);

    return [getData, setGetData];
};

/** Thunk — advance to next question */
export const MoveNextQuestion = () => (dispatch) => {
    try {
        dispatch(Action.moveNextAction());
    } catch (error) {
        console.error('Error moving to next question:', error);
    }
};

/** Thunk — go back to previous question */
export const MovePrevQuestion = () => (dispatch) => {
    try {
        dispatch(Action.movePrevAction());
    } catch (error) {
        console.error('Error moving to previous question:', error);
    }
};
